export const html: Record<Lang, string> = {
  it: "<section>\r\n<h2>Dove fare la spesa</h2>\r\n<p>Qui trovate minimarket, supermercati e negozi utili vicino alla casa o comodi da raggiungere in auto.</p>\r\n<div class=\"shop-grid\">\r\n<div class=\"shop-card featured\">\r\n<div class=\"shop-img\">\r\n<img alt=\"Minimarket da Nello\" src=\"/assets/da-nello.jpg\"/>\r\n</div>\r\n<h3>Minimarket da Nello</h3>\r\n<p>È il minimarket vicino casa, raggiungibile a piedi. Comodo per piccole necessità, acqua, snack, prodotti essenziali o una spesa veloce senza prendere l'auto.</p>\r\n<div class=\"shop-note\">Consigliato per: spesa veloce e prodotti essenziali.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=Minimarket+Da+Nello+Brignano+Salerno\" target=\"_blank\">📍 Portami lì</a>\r\n</div>\r\n</div>\r\n<div class=\"shop-card\">\r\n<div class=\"shop-img\">\r\n<img alt=\"CONAD Superstore Le Cotoniere\" src=\"/assets/conad-cotoniere.jpg\"/>\r\n</div>\r\n<h3>CONAD Superstore - Le Cotoniere</h3>\r\n<p>Consigliato per la spesa principale: è grande, ben fornito e si trova nel centro commerciale Le Cotoniere. Trovate banco gastronomia, pescheria, macelleria, frutta, verdura e prodotti confezionati.</p>\r\n<div class=\"shop-note\">Orario indicativo: tutti i giorni 09:00–21:00. Parcheggio disponibile nel centro commerciale.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=CONAD+Superstore+Le+Cotoniere+Salerno\" target=\"_blank\">📍 Portami lì</a>\r\n</div>\r\n</div>\r\n<div class=\"shop-card\">\r\n<div class=\"shop-img\">\r\n<img alt=\"MD\" onerror=\"this.onerror=null; this.src='assets/garden-main.jpg';\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/4/41/MD_Italia_Logo.svg/500px-MD_Italia_Logo.svg.png\"/>\r\n</div>\r\n<h3>MD - Via Irno</h3>\r\n<p>Supermercato/discount comodo e facile da raggiungere, conosciuto per prezzi convenienti, soprattutto per frutta, verdura e prodotti di uso quotidiano.</p>\r\n<div class=\"shop-note\">Orari indicativi: lun 08:30–20:30, mar 08:00–20:30, mer-ven 08:30–20:30, sab chiuso, dom 08:30–13:30.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=MD+Via+Irno+Salerno\" target=\"_blank\">📍 Portami lì</a>\r\n</div>\r\n</div>\r\n<div class=\"shop-card\">\r\n<div class=\"shop-img\">\r\n<img alt=\"Sole 365\" onerror=\"this.onerror=null; this.src='assets/garden-main.jpg';\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/2/22/Sole_365_Logo.svg/500px-Sole_365_Logo.svg.png\"/>\r\n</div>\r\n<h3>Sole 365 - Zona Vinciprova</h3>\r\n<p>Supermercato comodo se vi trovate in zona Vinciprova o vicino alla stazione. È utile per una spesa completa, prodotti freschi e acquisti quotidiani.</p>\r\n<div class=\"shop-note\">Consigliato se siete già in città o rientrate dalla zona stazione/Vinciprova.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=Sole+365+Vinciprova+Salerno\" target=\"_blank\">📍 Portami lì</a>\r\n</div>\r\n</div>\r\n<div class=\"shop-card\">\r\n<div class=\"shop-img\">\r\n<img alt=\"Eurospin\" onerror=\"this.onerror=null; this.src='assets/garden-main.jpg';\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/5/57/Eurospin_New_Logo.svg/500px-Eurospin_New_Logo.svg.png\"/>\r\n</div>\r\n<h3>Eurospin - Zona Grand Hotel Salerno</h3>\r\n<p>Discount grande e conveniente, utile se volete fare una spesa più economica o comprare diversi prodotti. È comodo se passate dalla zona del Grand Hotel Salerno.</p>\r\n<div class=\"shop-note\">Consigliato per: spesa conveniente, prodotti confezionati, bibite, snack e prodotti per più giorni.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=Eurospin+Grand+Hotel+Salerno\" target=\"_blank\">📍 Portami lì</a>\r\n</div>\r\n</div>\r\n<div class=\"shop-card\">\r\n<div class=\"shop-img\">\r\n<img alt=\"Lidl\" onerror=\"this.onerror=null; this.src='assets/garden-main.jpg';\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/Lidl-Logo.svg/500px-Lidl-Logo.svg.png\"/>\r\n</div>\r\n<h3>Lidl - Mariconda</h3>\r\n<p>Discount tedesco in zona Mariconda, comodo per una spesa economica e ben fornita. Ottimo per prodotti da forno, frutta, verdura e offerte settimanali.</p>\r\n<div class=\"shop-note\">Orario indicativo: tutti i giorni 08:00–21:00, domenica 08:30–20:30. Parcheggio disponibile.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=Lidl+Mariconda+Salerno\" target=\"_blank\">📍 Portami lì</a>\r\n</div>\r\n</div>\r\n<div class=\"shop-card\">\r\n<div class=\"shop-img\">\r\n<img alt=\"La Contadina Via Irno Salerno\" src=\"/assets/la-contadina.jpg\"/>\r\n</div>\r\n<h3>La Contadina - Via Irno</h3>\r\n<p>Negozio/caseificio consigliato per acquistare mozzarella di bufala campana, latticini e prodotti freschi. Non è un ristorante, ma è perfetto se volete comprare qualcosa di tipico da gustare a casa.</p>\r\n<div class=\"shop-note\">Consigliato per: mozzarella di bufala, latticini freschi e prodotti tipici campani.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=La+Contadina+Via+Irno+Salerno\" target=\"_blank\">📍 Portami lì</a>\r\n</div>\r\n</div>\r\n</div>\r\n</section>",
  en: "<section>\r\n<h2>Grocery shopping</h2>\r\n<p>Here you will find minimarkets, supermarkets and useful shops near the house or easy to reach by car.</p>\r\n<div class=\"shop-grid\">\r\n<div class=\"shop-card featured\">\r\n<div class=\"shop-img\">\r\n<img alt=\"Minimarket da Nello\" src=\"/assets/da-nello.jpg\"/>\r\n</div>\r\n<h3>Minimarket da Nello</h3>\r\n<p>This is the minimarket near the house, reachable on foot. Convenient for small needs, water, snacks, essentials or a quick shop without taking the car.</p>\r\n<div class=\"shop-note\">Recommended for: quick shopping and essentials.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=Minimarket+Da+Nello+Brignano+Salerno\" target=\"_blank\">📍 Take me there</a>\r\n</div>\r\n</div>\r\n<div class=\"shop-card\">\r\n<div class=\"shop-img\">\r\n<img alt=\"CONAD Superstore Le Cotoniere\" src=\"/assets/conad-cotoniere.jpg\"/>\r\n</div>\r\n<h3>CONAD Superstore - Le Cotoniere</h3>\r\n<p>Recommended for your main grocery shopping: it is large, well-stocked and located inside Le Cotoniere shopping centre. You will find deli counter, fish counter, butcher, fruit, vegetables and packaged products.</p>\r\n<div class=\"shop-note\">Indicative opening hours: every day 09:00–21:00. Parking available at the shopping centre.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=CONAD+Superstore+Le+Cotoniere+Salerno\" target=\"_blank\">📍 Take me there</a>\r\n</div>\r\n</div>\r\n<div class=\"shop-card\">\r\n<div class=\"shop-img\">\r\n<img alt=\"MD\" onerror=\"this.onerror=null; this.src='assets/garden-main.jpg';\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/4/41/MD_Italia_Logo.svg/500px-MD_Italia_Logo.svg.png\"/>\r\n</div>\r\n<h3>MD - Via Irno</h3>\r\n<p>A convenient and easy-to-reach discount supermarket, known for affordable prices, especially for fruit, vegetables and everyday products.</p>\r\n<div class=\"shop-note\">Indicative hours: Mon 08:30–20:30, Tue 08:00–20:30, Wed-Fri 08:30–20:30, Sat closed, Sun 08:30–13:30.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=MD+Via+Irno+Salerno\" target=\"_blank\">📍 Take me there</a>\r\n</div>\r\n</div>\r\n<div class=\"shop-card\">\r\n<div class=\"shop-img\">\r\n<img alt=\"Sole 365\" onerror=\"this.onerror=null; this.src='assets/garden-main.jpg';\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/2/22/Sole_365_Logo.svg/500px-Sole_365_Logo.svg.png\"/>\r\n</div>\r\n<h3>Sole 365 - Vinciprova area</h3>\r\n<p>A convenient supermarket if you are in the Vinciprova area or near the station. Useful for a full grocery shop, fresh products and everyday items.</p>\r\n<div class=\"shop-note\">Recommended if you are already in town or coming back from the station/Vinciprova area.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=Sole+365+Vinciprova+Salerno\" target=\"_blank\">📍 Take me there</a>\r\n</div>\r\n</div>\r\n<div class=\"shop-card\">\r\n<div class=\"shop-img\">\r\n<img alt=\"Eurospin\" onerror=\"this.onerror=null; this.src='assets/garden-main.jpg';\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/5/57/Eurospin_New_Logo.svg/500px-Eurospin_New_Logo.svg.png\"/>\r\n</div>\r\n<h3>Eurospin - Grand Hotel Salerno area</h3>\r\n<p>A large and affordable discount supermarket, useful if you want to save money or buy several products. Convenient if you pass through the Grand Hotel Salerno area.</p>\r\n<div class=\"shop-note\">Recommended for: budget shopping, packaged products, drinks, snacks and supplies for several days.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=Eurospin+Grand+Hotel+Salerno\" target=\"_blank\">📍 Take me there</a>\r\n</div>\r\n</div>\r\n<div class=\"shop-card\">\r\n<div class=\"shop-img\">\r\n<img alt=\"Lidl\" onerror=\"this.onerror=null; this.src='assets/garden-main.jpg';\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/Lidl-Logo.svg/500px-Lidl-Logo.svg.png\"/>\r\n</div>\r\n<h3>Lidl - Mariconda</h3>\r\n<p>German discount supermarket in the Mariconda area, convenient for budget-friendly and well-stocked shopping. Great for baked goods, fruit, vegetables and weekly offers.</p>\r\n<div class=\"shop-note\">Indicative hours: every day 08:00–21:00, Sunday 08:30–20:30. Parking available.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=Lidl+Mariconda+Salerno\" target=\"_blank\">📍 Take me there</a>\r\n</div>\r\n</div>\r\n<div class=\"shop-card\">\r\n<div class=\"shop-img\">\r\n<img alt=\"La Contadina Via Irno Salerno\" src=\"/assets/la-contadina.jpg\"/>\r\n</div>\r\n<h3>La Contadina - Via Irno</h3>\r\n<p>Recommended dairy shop to buy buffalo mozzarella from Campania, dairy products and fresh products. It is not a restaurant, but it is perfect if you want to buy something local to enjoy at home.</p>\r\n<div class=\"shop-note\">Recommended for: buffalo mozzarella, fresh dairy products and typical Campania products.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=La+Contadina+Via+Irno+Salerno\" target=\"_blank\">📍 Take me there</a>\r\n</div>\r\n</div>\r\n</div>\r\n</section>",
  es: "<section>\r\n<h2>Dónde hacer la compra</h2>\r\n<p>Aquí encontraréis minimarkets, supermercados y tiendas útiles cerca de la casa o fáciles de alcanzar en coche.</p>\r\n<div class=\"shop-grid\">\r\n<div class=\"shop-card featured\">\r\n<div class=\"shop-img\">\r\n<img alt=\"Minimarket da Nello\" src=\"/assets/da-nello.jpg\"/>\r\n</div>\r\n<h3>Minimarket da Nello</h3>\r\n<p>Es el minimarket cerca de la casa, se puede llegar a pie. Cómodo para pequeñas necesidades, agua, snacks, productos básicos o una compra rápida sin usar el coche.</p>\r\n<div class=\"shop-note\">Recomendado para: compra rápida y productos básicos.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=Minimarket+Da+Nello+Brignano+Salerno\" target=\"_blank\">📍 Llévame allí</a>\r\n</div>\r\n</div>\r\n<div class=\"shop-card\">\r\n<div class=\"shop-img\">\r\n<img alt=\"CONAD Superstore Le Cotoniere\" src=\"/assets/conad-cotoniere.jpg\"/>\r\n</div>\r\n<h3>CONAD Superstore - Le Cotoniere</h3>\r\n<p>Recomendado para la compra principal: es grande, bien abastecido y está dentro del centro comercial Le Cotoniere. Encontraréis charcutería, pescadería, carnicería, fruta, verdura y productos envasados.</p>\r\n<div class=\"shop-note\">Horario orientativo: todos los días 09:00–21:00. Aparcamiento disponible en el centro comercial.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=CONAD+Superstore+Le+Cotoniere+Salerno\" target=\"_blank\">📍 Llévame allí</a>\r\n</div>\r\n</div>\r\n<div class=\"shop-card\">\r\n<div class=\"shop-img\">\r\n<img alt=\"MD\" onerror=\"this.onerror=null; this.src='assets/garden-main.jpg';\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/4/41/MD_Italia_Logo.svg/500px-MD_Italia_Logo.svg.png\"/>\r\n</div>\r\n<h3>MD - Via Irno</h3>\r\n<p>Supermercado/discount cómodo y fácil de alcanzar, conocido por sus precios convenientes, especialmente en fruta, verdura y productos de uso diario.</p>\r\n<div class=\"shop-note\">Horario orientativo: lun 08:30–20:30, mar 08:00–20:30, mié-vie 08:30–20:30, sáb cerrado, dom 08:30–13:30.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=MD+Via+Irno+Salerno\" target=\"_blank\">📍 Llévame allí</a>\r\n</div>\r\n</div>\r\n<div class=\"shop-card\">\r\n<div class=\"shop-img\">\r\n<img alt=\"Sole 365\" onerror=\"this.onerror=null; this.src='assets/garden-main.jpg';\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/2/22/Sole_365_Logo.svg/500px-Sole_365_Logo.svg.png\"/>\r\n</div>\r\n<h3>Sole 365 - Zona Vinciprova</h3>\r\n<p>Supermercado cómodo si estáis en la zona de Vinciprova o cerca de la estación. Útil para una compra completa, productos frescos y artículos diarios.</p>\r\n<div class=\"shop-note\">Recomendado si ya estáis en la ciudad o volvéis de la zona estación/Vinciprova.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=Sole+365+Vinciprova+Salerno\" target=\"_blank\">📍 Llévame allí</a>\r\n</div>\r\n</div>\r\n<div class=\"shop-card\">\r\n<div class=\"shop-img\">\r\n<img alt=\"Eurospin\" onerror=\"this.onerror=null; this.src='assets/garden-main.jpg';\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/5/57/Eurospin_New_Logo.svg/500px-Eurospin_New_Logo.svg.png\"/>\r\n</div>\r\n<h3>Eurospin - Zona Grand Hotel Salerno</h3>\r\n<p>Discount grande y económico, útil si queréis ahorrar o comprar varios productos. Cómodo si pasáis por la zona del Grand Hotel Salerno.</p>\r\n<div class=\"shop-note\">Recomendado para: compra económica, productos envasados, bebidas, snacks y productos para varios días.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=Eurospin+Grand+Hotel+Salerno\" target=\"_blank\">📍 Llévame allí</a>\r\n</div>\r\n</div>\r\n<div class=\"shop-card\">\r\n<div class=\"shop-img\">\r\n<img alt=\"Lidl\" onerror=\"this.onerror=null; this.src='assets/garden-main.jpg';\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/Lidl-Logo.svg/500px-Lidl-Logo.svg.png\"/>\r\n</div>\r\n<h3>Lidl - Mariconda</h3>\r\n<p>Discount alemán en la zona Mariconda, cómodo para una compra económica y bien surtida. Ideal para productos de panadería, fruta, verdura y ofertas semanales.</p>\r\n<div class=\"shop-note\">Horario orientativo: todos los días 08:00–21:00, domingo 08:30–20:30. Aparcamiento disponible.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=Lidl+Mariconda+Salerno\" target=\"_blank\">📍 Llévame allí</a>\r\n</div>\r\n</div>\r\n<div class=\"shop-card\">\r\n<div class=\"shop-img\">\r\n<img alt=\"La Contadina Via Irno Salerno\" src=\"/assets/la-contadina.jpg\"/>\r\n</div>\r\n<h3>La Contadina - Via Irno</h3>\r\n<p>Tienda/caseificio recomendado para comprar mozzarella de búfala campana, lácteos y productos frescos. No es un restaurante, pero es perfecto si queréis comprar algo típico para disfrutar en casa.</p>\r\n<div class=\"shop-note\">Recomendado para: mozzarella de búfala, lácteos frescos y productos típicos de Campania.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=La+Contadina+Via+Irno+Salerno\" target=\"_blank\">📍 Llévame allí</a>\r\n</div>\r\n</div>\r\n</div>\r\n</section>",
  fr: "<section>\r\n<h2>Où faire les courses</h2>\r\n<p>Vous trouverez ici des supérettes, supermarchés et magasins utiles près de la maison ou faciles d'accès en voiture.</p>\r\n<div class=\"shop-grid\">\r\n<div class=\"shop-card featured\">\r\n<div class=\"shop-img\">\r\n<img alt=\"Minimarket da Nello\" src=\"/assets/da-nello.jpg\"/>\r\n</div>\r\n<h3>Minimarket da Nello</h3>\r\n<p>C'est la supérette près de la maison, accessible à pied. Pratique pour les petites courses, l'eau, les snacks, les produits essentiels ou un achat rapide sans prendre la voiture.</p>\r\n<div class=\"shop-note\">Conseillé pour : petites courses et produits essentiels.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=Minimarket+Da+Nello+Brignano+Salerno\" target=\"_blank\">📍 M’y emmener</a>\r\n</div>\r\n</div>\r\n<div class=\"shop-card\">\r\n<div class=\"shop-img\">\r\n<img alt=\"CONAD Superstore Le Cotoniere\" src=\"/assets/conad-cotoniere.jpg\"/>\r\n</div>\r\n<h3>CONAD Superstore - Le Cotoniere</h3>\r\n<p>Conseillé pour les grandes courses : il est grand, bien fourni et situé dans le centre commercial Le Cotoniere. Vous y trouverez traiteur, poissonnerie, boucherie, fruits, légumes et produits emballés.</p>\r\n<div class=\"shop-note\">Horaires indicatifs : tous les jours 09h00–21h00. Parking disponible dans le centre commercial.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=CONAD+Superstore+Le+Cotoniere+Salerno\" target=\"_blank\">📍 M’y emmener</a>\r\n</div>\r\n</div>\r\n<div class=\"shop-card\">\r\n<div class=\"shop-img\">\r\n<img alt=\"MD\" onerror=\"this.onerror=null; this.src='assets/garden-main.jpg';\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/4/41/MD_Italia_Logo.svg/500px-MD_Italia_Logo.svg.png\"/>\r\n</div>\r\n<h3>MD - Via Irno</h3>\r\n<p>Supermarché discount pratique et facile d'accès, connu pour ses prix avantageux, surtout pour les fruits, légumes et produits du quotidien.</p>\r\n<div class=\"shop-note\">Horaires indicatifs : lun 08h30–20h30, mar 08h00–20h30, mer-ven 08h30–20h30, sam fermé, dim 08h30–13h30.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=MD+Via+Irno+Salerno\" target=\"_blank\">📍 M’y emmener</a>\r\n</div>\r\n</div>\r\n<div class=\"shop-card\">\r\n<div class=\"shop-img\">\r\n<img alt=\"Sole 365\" onerror=\"this.onerror=null; this.src='assets/garden-main.jpg';\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/2/22/Sole_365_Logo.svg/500px-Sole_365_Logo.svg.png\"/>\r\n</div>\r\n<h3>Sole 365 - Quartier Vinciprova</h3>\r\n<p>Supermarché pratique si vous êtes dans le quartier Vinciprova ou près de la gare. Utile pour des courses complètes, des produits frais et les achats du quotidien.</p>\r\n<div class=\"shop-note\">Conseillé si vous êtes déjà en ville ou si vous revenez de la zone gare/Vinciprova.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=Sole+365+Vinciprova+Salerno\" target=\"_blank\">📍 M’y emmener</a>\r\n</div>\r\n</div>\r\n<div class=\"shop-card\">\r\n<div class=\"shop-img\">\r\n<img alt=\"Eurospin\" onerror=\"this.onerror=null; this.src='assets/garden-main.jpg';\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/5/57/Eurospin_New_Logo.svg/500px-Eurospin_New_Logo.svg.png\"/>\r\n</div>\r\n<h3>Eurospin - Quartier Grand Hotel Salerno</h3>\r\n<p>Grand supermarché discount économique, utile si vous voulez faire des économies ou acheter plusieurs produits. Pratique si vous passez par le quartier du Grand Hotel Salerno.</p>\r\n<div class=\"shop-note\">Conseillé pour : courses économiques, produits emballés, boissons, snacks et achats pour plusieurs jours.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=Eurospin+Grand+Hotel+Salerno\" target=\"_blank\">📍 M’y emmener</a>\r\n</div>\r\n</div>\r\n<div class=\"shop-card\">\r\n<div class=\"shop-img\">\r\n<img alt=\"Lidl\" onerror=\"this.onerror=null; this.src='assets/garden-main.jpg';\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/Lidl-Logo.svg/500px-Lidl-Logo.svg.png\"/>\r\n</div>\r\n<h3>Lidl - Mariconda</h3>\r\n<p>Discount allemand dans le quartier Mariconda, pratique pour des courses économiques et bien fournies. Idéal pour les produits de boulangerie, fruits, légumes et offres hebdomadaires.</p>\r\n<div class=\"shop-note\">Horaires indicatifs : tous les jours 08h00–21h00, dimanche 08h30–20h30. Parking disponible.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=Lidl+Mariconda+Salerno\" target=\"_blank\">📍 M'y emmener</a>\r\n</div>\r\n</div>\r\n<div class=\"shop-card\">\r\n<div class=\"shop-img\">\r\n<img alt=\"La Contadina Via Irno Salerno\" src=\"/assets/la-contadina.jpg\"/>\r\n</div>\r\n<h3>La Contadina - Via Irno</h3>\r\n<p>Boutique/fromagerie conseillée pour acheter de la mozzarella di bufala campana, des produits laitiers et des produits frais. Ce n’est pas un restaurant, mais c’est parfait si vous voulez acheter quelque chose de typique à déguster à la maison.</p>\r\n<div class=\"shop-note\">Conseillé pour : mozzarella di bufala, produits laitiers frais et produits typiques de Campanie.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=La+Contadina+Via+Irno+Salerno\" target=\"_blank\">📍 M’y emmener</a>\r\n</div>\r\n</div>\r\n</div>\r\n</section>",
  de: "<section>\r\n<h2>Lebensmittel einkaufen</h2>\r\n<p>Hier findet ihr Minimärkte, Supermärkte und nützliche Geschäfte in der Nähe des Hauses oder bequem mit dem Auto erreichbar.</p>\r\n<div class=\"shop-grid\">\r\n<div class=\"shop-card featured\">\r\n<div class=\"shop-img\">\r\n<img alt=\"Minimarket da Nello\" src=\"/assets/da-nello.jpg\"/>\r\n</div>\r\n<h3>Minimarket da Nello</h3>\r\n<p>Das ist der Minimarkt in der Nähe des Hauses, zu Fuß erreichbar. Praktisch für kleine Besorgungen, Wasser, Snacks, Grundprodukte oder einen schnellen Einkauf ohne Auto.</p>\r\n<div class=\"shop-note\">Empfohlen für: schnellen Einkauf und Grundprodukte.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=Minimarket+Da+Nello+Brignano+Salerno\" target=\"_blank\">📍 Bring mich hin</a>\r\n</div>\r\n</div>\r\n<div class=\"shop-card\">\r\n<div class=\"shop-img\">\r\n<img alt=\"CONAD Superstore Le Cotoniere\" src=\"/assets/conad-cotoniere.jpg\"/>\r\n</div>\r\n<h3>CONAD Superstore - Le Cotoniere</h3>\r\n<p>Empfohlen für den großen Wocheneinkauf: Es ist groß, gut sortiert und liegt im Einkaufszentrum Le Cotoniere. Ihr findet Feinkosttheke, Fischtheke, Metzgerei, Obst, Gemüse und abgepackte Produkte.</p>\r\n<div class=\"shop-note\">Ungefähre Öffnungszeiten: täglich 09:00–21:00 Uhr. Parken im Einkaufszentrum möglich.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=CONAD+Superstore+Le+Cotoniere+Salerno\" target=\"_blank\">📍 Bring mich hin</a>\r\n</div>\r\n</div>\r\n<div class=\"shop-card\">\r\n<div class=\"shop-img\">\r\n<img alt=\"MD\" onerror=\"this.onerror=null; this.src='assets/garden-main.jpg';\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/4/41/MD_Italia_Logo.svg/500px-MD_Italia_Logo.svg.png\"/>\r\n</div>\r\n<h3>MD - Via Irno</h3>\r\n<p>Ein bequemer und leicht erreichbarer Supermarkt/Discounter, bekannt für günstige Preise, vor allem bei Obst, Gemüse und Alltagsprodukten.</p>\r\n<div class=\"shop-note\">Ungefähre Öffnungszeiten: Mo 08:30–20:30, Di 08:00–20:30, Mi–Fr 08:30–20:30, Sa geschlossen, So 08:30–13:30.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=MD+Via+Irno+Salerno\" target=\"_blank\">📍 Bring mich hin</a>\r\n</div>\r\n</div>\r\n<div class=\"shop-card\">\r\n<div class=\"shop-img\">\r\n<img alt=\"Sole 365\" onerror=\"this.onerror=null; this.src='assets/garden-main.jpg';\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/2/22/Sole_365_Logo.svg/500px-Sole_365_Logo.svg.png\"/>\r\n</div>\r\n<h3>Sole 365 - Gebiet Vinciprova</h3>\r\n<p>Ein praktischer Supermarkt, wenn ihr im Gebiet Vinciprova oder in der Nähe des Bahnhofs seid. Nützlich für den kompletten Einkauf, frische Produkte und Alltagsgegenstände.</p>\r\n<div class=\"shop-note\">Empfohlen, wenn ihr schon in der Stadt seid oder vom Bereich Bahnhof/Vinciprova zurückkommt.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=Sole+365+Vinciprova+Salerno\" target=\"_blank\">📍 Bring mich hin</a>\r\n</div>\r\n</div>\r\n<div class=\"shop-card\">\r\n<div class=\"shop-img\">\r\n<img alt=\"Eurospin\" onerror=\"this.onerror=null; this.src='assets/garden-main.jpg';\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/5/57/Eurospin_New_Logo.svg/500px-Eurospin_New_Logo.svg.png\"/>\r\n</div>\r\n<h3>Eurospin - Gebiet Grand Hotel Salerno</h3>\r\n<p>Ein großer und günstiger Discounter, nützlich, wenn ihr sparen oder mehrere Produkte kaufen wollt. Praktisch, wenn ihr durch das Gebiet des Grand Hotel Salerno fahrt.</p>\r\n<div class=\"shop-note\">Empfohlen für: günstigen Einkauf, abgepackte Produkte, Getränke, Snacks und Vorräte für mehrere Tage.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=Eurospin+Grand+Hotel+Salerno\" target=\"_blank\">📍 Bring mich hin</a>\r\n</div>\r\n</div>\r\n<div class=\"shop-card\">\r\n<div class=\"shop-img\">\r\n<img alt=\"Lidl\" onerror=\"this.onerror=null; this.src='assets/garden-main.jpg';\" src=\"https://upload.wikimedia.org/wikipedia/commons/thumb/9/91/Lidl-Logo.svg/500px-Lidl-Logo.svg.png\"/>\r\n</div>\r\n<h3>Lidl - Mariconda</h3>\r\n<p>Deutscher Discounter im Gebiet Mariconda, praktisch für einen günstigen und gut sortierten Einkauf. Ideal für Backwaren, Obst, Gemüse und Wochenangebote.</p>\r\n<div class=\"shop-note\">Ungefähre Öffnungszeiten: täglich 08:00–21:00, Sonntag 08:30–20:30. Parken möglich.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=Lidl+Mariconda+Salerno\" target=\"_blank\">📍 Bring mich hin</a>\r\n</div>\r\n</div>\r\n<div class=\"shop-card\">\r\n<div class=\"shop-img\">\r\n<img alt=\"La Contadina Via Irno Salerno\" src=\"/assets/la-contadina.jpg\"/>\r\n</div>\r\n<h3>La Contadina - Via Irno</h3>\r\n<p>Geschäft/Käserei, empfohlen für den Kauf von kampanischer Büffelmozzarella, Milchprodukten und frischen Produkten. Es ist kein Restaurant, aber perfekt, wenn ihr etwas Typisches kaufen und zu Hause genießen wollt.</p>\r\n<div class=\"shop-note\">Empfohlen für: Büffelmozzarella, frische Milchprodukte und typische Produkte aus Kampanien.</div>\r\n<div class=\"shop-actions\">\r\n<a class=\"shop-btn\" href=\"https://www.google.com/maps/search/?api=1&amp;query=La+Contadina+Via+Irno+Salerno\" target=\"_blank\">📍 Bring mich hin</a>\r\n</div>\r\n</div>\r\n</div>\r\n</section>",
};
